#include <vector>
#include <numeric>
#include <algorithm>

class Solution {
public:
    int maxSumOfMSubarrays(std::vector<int>& nums, int m, int k) {
        int n = nums.size();
        if (n < m * k) return 0;
        std::vector<int> kSums;
        int curSum = 0;
        for (int i = 0; i < k; ++i) curSum += nums[i];
        kSums.push_back(curSum);
        for (int i = k; i < n; ++i) {
            curSum += nums[i] - nums[i - k];
            kSums.push_back(curSum);
        }
        int numW = kSums.size();
        std::vector<std::vector<int>> dp(m + 1, std::vector<int>(numW + 1, 0));
        for (int j = 1; j <= m; ++j) {
            for (int i = 0; i < numW; ++i) {
                int prev = (i >= k - 1) ? dp[j - 1][i - k + 1] : 0;
                dp[j][i + 1] = std::max(dp[j][i], prev + kSums[i]);
            }
        }
        return dp[m][numW];
    }
};

import java.util.*;

class Solution {
    public int maxSumOfMSubarrays(int[] nums, int m, int k) {
        int n = nums.length;
        if (n < m * k) return 0;
        int[] kSums = new int[n - k + 1];
        int cur = 0;
        for (int i = 0; i < k; i++) cur += nums[i];
        kSums[0] = cur;
        for (int i = k; i < n; i++) {
            cur += nums[i] - nums[i - k];
            kSums[i - k + 1] = cur;
        }
        int numW = kSums.length;
        int[][] dp = new int[m + 1][numW + 1];
        for (int j = 1; j <= m; j++) {
            for (int i = 0; i < numW; i++) {
                int prev = (i >= k - 1) ? dp[j - 1][i - k + 1] : 0;
                dp[j][i + 1] = Math.max(dp[j][i], prev + kSums[i]);
            }
        }
        return dp[m][numW];
    }
}

